head.script:
scwin.init = function() {
    var jsonData1 = [{
            "col1": "1111",
            "col2": "AAAA"
        },
        {
            "col1": "2222",
            "col2": "BBBB"
        },
    ];
    dataList2.setJSON(jsonData1);
    var jsonData = [{
            "col2": "bbbb1",
            "col3": "cccc1",
            "col4": "dddd1"
        },
        {
            "col2": "bbbb2",
            "col3": "cccc2",
            "col4": "dddd2"
        },
        {
            "col2": "bbbb3",
            "col3": "cccc3",
            "col4": "dddd3"
        },
        {
            "col2": "bbbb4",
            "col3": "cccc4",
            "col4": "dddd4"
        },
    ];
    dataList1.setJSON(jsonData);
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_column7').textContent == '메모'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 26-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
